// Flattened word list with section/page indices for stats tracking
export interface FlatVocabItem extends VocabItem {
  sectionId: string;
  pageIndex: number;
  itemIndex: number;
  globalId: string;
}

export const ALL_WORDS: FlatVocabItem[] = VOCAB_SECTIONS.flatMap((section) =>
  section.pages.flatMap((page) =>
    page.items.map((item, itemIndex) => ({
      ...item,
      sectionId: section.id,
      pageIndex: page.pageIndex,
      itemIndex,
      globalId: `${section.id}-${page.pageIndex}-${itemIndex}`,
    }))
  )
);

export function getSection(id: string): VocabSection | undefined {
  return VOCAB_SECTIONS.find((s) => s.id === id);
}

export function getPage(sectionId: string, pageIndex: number): VocabPage | undefined {
  return getSection(sectionId)?.pages[pageIndex];
}
